 void Help(){Box(new Rect(0,0,540,960),new Color(.04f,.065f,.09f,.98f));Text(new Rect(32,42,475,52),"플레이 방법",28,ink,true);string instructions="1  덱 탭에서 생산·기능·마법 카드 8종을 선택합니다.\n\n2  카드 탭 → 필드를 누른 채 위치를 고릅니다. 초록색 위치에서 손을 떼면 결제·사용합니다. 빨간 위치나 필드 밖에서 떼면 취소됩니다.\n\n3  건물을 누르고 합성 대상을 선택합니다. 마법은 합성 불가입니다. 같은 건물과 같은 티어만 합칩니다. T4 버블은 길게 눌러 설명, 짧게 눌러 선택합니다.\n\n4  1칸 금광을 눌러 최대 6명까지 일꾼을 추가합니다. 장애물을 누르면 3골드로 제거합니다.\n\n5  새로고침 → 교체할 카드 한 장. 최초 1회, 사용 후 30초에 갱신됩니다.\n\n6  던전 맵에서는 고정 적을 처치합니다. 보스의 소울 10으로 영웅을 소환합니다. 영웅은 처치 경험치로 성장하고 죽으면 20초 뒤 같은 레벨로 부활합니다.\n\n7  적 기지를 파괴하면 승리합니다. 영웅 성장과 골드는 한 판에서만 유지됩니다.";Text(new Rect(32,119,475,729),instructions,17,ink);if(Button(new Rect(32,871,476,53),"확인",blue))help=false;}
 void PracticeMaterials(){if(!sim.practice)return;string k=deck.FirstOrDefault(id=>catalog.Find(id)!=null)??"fence";int count=0;for(int y=0;y<10;y++)for(int x=0;x<10;x++)if(count<2&&sim.CanPlace(k,0,0,x,y,out var why)){var b=sim.AddBuilding(k,0,0,x,y);b.tier=3;b.built=sim.time;b.maxHp=b.hp=(catalog.Find(k)?.buildingHp??catalog.Card(k).hp)*2.56f;b.invested=0;count++;}sim.message=count==2?"T3 두 건물을 합쳐 T4를 검증하세요":"재료 공간이 부족합니다";}
 Vector2 Project(Vector3 p){var s=cam.WorldToScreenPoint(p);return new Vector2((s.x-uiOffset.x)/uiScale,(Screen.height-s.y-uiOffset.y)/uiScale);}
 void DrawBars(){if(cam==null)return;foreach(var b in sim.buildings.Where(b=>b.alive&&b.field==field)){var p=Project(new Vector3(b.pos.x-(sim.Width(field)/2f),.9f,b.pos.y-(sim.Height(field)/2f)));if(p.y<arena.y+25||p.y>arena.yMax-28)continue;float w=b.kind=="base"?79:42;Box(new Rect(p.x-w/2,p.y,w,5),new Color(.08f,.12f,.12f));Box(new Rect(p.x-w/2,p.y,w*Mathf.Clamp01(b.hp/b.maxHp),5),b.team==0?blue:red);if(b.kind!="base"){Text(new Rect(p.x-20,p.y+7,60,19),"T"+b.tier+(b.Pending?" !":""),11,b.Pending?gold:Color.white);if(b==selected)Box(new Rect(p.x-25,p.y-4,50,2),gold);}}
  DrawWorkers();
  foreach(var f in sim.fighters.Where(f=>f.alive&&f.field==field&&(f.hp<f.maxHp||f.hero||f.boss))){var p=Project(World(f.pos,.82f));if(!arena.Contains(p))continue;Box(new Rect(p.x-15,p.y,30,3),panel);Box(new Rect(p.x-15,p.y,30*Mathf.Clamp01(f.hp/f.maxHp),3),f.hero?gold:f.team==0?blue:red);if(f.shield>0)Box(new Rect(p.x-15,p.y+4,30,2),new Color(.7f,.8f,1));}
 }
 Vector3 World(Vector2 pos,float y=0)=>new Vector3(pos.x-(sim.Width(field)/2f),y,pos.y-(sim.Height(field)/2f));
 void RenderWorld(){cam.rect=new Rect((uiOffset.x)/Screen.width,(Screen.height-uiOffset.y-(arena.y+arena.height)*uiScale)/Screen.height,540*uiScale/Screen.width,arena.height*uiScale/Screen.height);cam.orthographicSize=field==0?9.0f:5.2f;
  if(shownField!=field||rockCount!=sim.removed.Count){RebuildTerrain();ZoneLines();shownField=field;rockCount=sim.removed.Count;}
  var alive=new HashSet<int>();foreach(var b in sim.buildings){if(!b.alive||b.field!=field)continue;alive.Add(b.id);string key=b.kind+b.tier+"/"+b.branch;if(!views.ContainsKey(b.id)||viewKeys[b.id]!=key){if(views.TryGetValue(b.id,out var old))Destroy(old);views[b.id]=BuildingModel(b);viewKeys[b.id]=key;}views[b.id].transform.position=World(b.pos);}
