  if(f.tier>=3||f.hero)Part(root,PrimitiveType.Cube,new Vector3(0,.74f+lift,0),new Vector3(.32f,.13f,.31f),f.hero?gold:new Color(.47f,.51f,.55f));root.transform.localScale=Vector3.one*scale*.58f;return root;
